//
// Golden vectors for mpo_vfpu.
//
// The vectors are generated by running PPSSPP's own code (built only into the
// test-only mpo_vfpu_golden_gen) over deterministic inputs, and stored as one
// 64-bit digest per instruction spec or math function in
// profiles/mpo/tests/data/vfpu_golden.txt:
//
//   op  <spec> <seed> <count> <digest>  final CPU states of <count> cases, by PPSSPP
//   fn  <name> <seed> <count> <digest>  results of <count> calls, by PPSSPP
//   pin <spec> <seed> <count> <digest>  the same cases as op, by mpo_vfpu itself
//
// op digests hash every NaN in an FPR or VFPU lane as one canonical NaN:
// PPSSPP leaves NaN payloads to the compiler (difftest::Policy). Everything
// else, and every fn result, is compared bit for bit. pin digests are exact:
// they lock the NaNs mpo_vfpu pins (vfpu::fadd/fmul) so they cannot drift
// between compilers or platforms.
//
// mpo_vfpu_golden_test recomputes every line with mpo_vfpu alone, so CI does
// not need PPSSPP. When a line differs, the difftest
// (mpo_difftest --b ppsspp --spec <spec>) shows the individual cases.

#pragma once

#include <cstdint>
#include <string>
#include <vector>

#include "difftest/difftest.hpp"
#include "golden/vfpu_functions.hpp"

namespace mpo::golden {

struct Entry {
    std::string kind; // "op", "fn" or "pin"
    std::string name;
    std::uint64_t seed = 0;
    int count = 0;
    std::uint64_t digest = 0;
};

// What the golden file covers: every VFPU spec of the difftest and the prefix
// sequences (as op and pin), and every scalar math function.
std::vector<Entry> plan();

// Digest of the final states of an op/pin entry's cases run by `executor`
// (NaN-canonical for op, exact for pin).
bool digest_op(const Entry &entry, difftest::Executor &executor, std::uint64_t *digest,
               std::string *error);

std::string format(const Entry &entry);
bool parse(const std::string &line, Entry *entry);

} // namespace mpo::golden
